from queue import PriorityQueue
import heapq


def shortest_path(edges, start, end):
    # Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed")

    # If start is same as end
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    # Dijkstra's algorithm
    # dist[node] = shortest distance from start to node
    dist = {start: 0}
    prev = {}  # predecessor node for each node

    # Priority queue: (distance, node)
    pq = [(0, start)]
    visited = set()

    while pq:
        d, u = heapq.heappop(pq)

        if u in visited:
            continue

        visited.add(u)

        # If we reached the end node, we can stop early
        if u == end:
            break

        if u not in graph:
            continue

        for v, w in graph[u]:
            new_dist = d + w
            if v not in dist or new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist, v))

    if end not in dist:
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current != start:
        path.append(current)
        current = prev[current]
    path.append(start)
    path.reverse()

    return (dist[end], path)
